INSERT OR IGNORE INTO auth_users (id, email, password_hash) VALUES ('4ca66bf1-1b3c-5daf-b764-df426c3b9574', 'linden-studio@designers.artisanmurals.invalid', 'disabled');
INSERT OR REPLACE INTO designer_profiles (user_id, full_name, studio_name, country, bio, styles, status, trusted, tagline, response_label, turnaround_days) VALUES ('4ca66bf1-1b3c-5daf-b764-df426c3b9574', 'Linden Studio', 'Linden Studio', 'Toronto, Canada', 'We paint big scenes the old way: layer by layer, animal by animal. Every mural is a single picture made to cover a whole wall without a repeat.', '["Murals", "Jungle", "Animals", "Painterly"]', 'approved', 1, 'Painterly jungles and wildlife scenes', 'Replies within an hour', 5);
